async function failing() {
  throw new Error('x');
}

async function a() {
  try {
    return failing();
  } catch {
    return 'ditangkap a';
  }
}

async function b() {
  try {
    return await failing();
  } catch {
    return 'ditangkap b';
  }
}

(async () => {
  await a().then((v) => console.log(v), () => console.log('a ditolak'));
  await b().then((v) => console.log(v), () => console.log('b ditolak'));
})();

